import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as n,c as s,e as a}from"./app-26293047.js";const o={},c=a(`<h1 id="docker-desktop-docker-桌面版图形应用-容器管理" tabindex="-1"><a class="header-anchor" href="#docker-desktop-docker-桌面版图形应用-容器管理" aria-hidden="true">#</a> docker-desktop（Docker 桌面版图形应用（容器管理））</h1><blockquote><p>Homebrew 版本 cask ｜ 主页：见官方文档 ｜ 安装：<code>brew install docker-desktop</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>docker-desktop 是 Docker 官方推出的<strong>桌面版图形应用</strong>，以图形界面（菜单栏图标、Dashboard 面板）管理本地容器与镜像，让普通开发者无需记忆大量 <code>docker</code> 命令也能完成拉取镜像、运行/停止容器、查看日志等日常操作。</p><p>它解决的核心问题是：<strong>在 macOS 上以最省心的方式运行 Docker 引擎</strong>。Docker 依赖 Linux 内核特性（cgroups、namespaces），无法在 macOS 上原生运行，docker-desktop 通过内置的 Linux 虚拟机（HyperKit / Virtualization.framework）在后台静默承载 Docker 引擎，用户只需启动应用即可获得可用的 <code>docker</code> 命令。典型应用场景：本地搭建开发环境、一键运行 MySQL/Redis/Postgres 等中间件、快速验证别人分享的镜像或 compose 工程。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>docker-desktop 是 Homebrew 的 <strong>cask</strong> 类软件（带 GUI 的桌面应用，不是 command-line 类），因此安装、升级、卸载都走 <code>brew install --cask</code> / <code>--cask</code> 一族：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装（cask 安装到 /Applications）</span>
brew <span class="token function">install</span> <span class="token parameter variable">--cask</span> docker-desktop

<span class="token comment"># 升级到最新版（cask 也支持 upgrade）</span>
brew upgrade <span class="token parameter variable">--cask</span> docker-desktop

<span class="token comment"># 卸载</span>
brew uninstall <span class="token parameter variable">--cask</span> docker-desktop

<span class="token comment"># 验证安装：应用已放入应用程序目录</span>
<span class="token function">ls</span> /Applications/Docker.app

<span class="token comment"># 启动应用后（首次会弹出许可协议与初始化向导，需同意并输入系统密码授权内核扩展/虚拟化）</span>
<span class="token function">open</span> <span class="token parameter variable">-a</span> Docker

<span class="token comment"># 等待引擎就绪后再验证 docker 命令是否可用</span>
<span class="token function">docker</span> <span class="token parameter variable">--version</span>
<span class="token function">docker</span> info
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：cask 只安装应用本体，<strong>不自动启动</strong>。第一次需要手动打开 Docker.app 完成初始化，之后引擎才会在后台运行，<code>docker</code> 命令才有响应。</p></blockquote><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><p>docker-desktop 日常使用分两块：一是<strong>图形界面操作</strong>（点菜单栏图标、进 Dashboard），二是<strong>命令行操作</strong>（引擎就绪后就是标准 <code>docker</code> 命令）。以下以命令行为主：</p><table><thead><tr><th>命令</th><th>参数说明</th><th>示例 / 说明</th></tr></thead><tbody><tr><td><code>open -a Docker</code></td><td>启动 Docker 桌面版应用</td><td><code>open -a Docker</code>（也可点 Finder 里的 Docker.app）</td></tr><tr><td><code>docker --version</code></td><td>查看 docker 客户端版本</td><td><code>docker --version</code>（应输出 <code>Docker version 24.x.x</code> 之类）</td></tr><tr><td><code>docker info</code></td><td>查看引擎/守护进程信息，判断是否就绪</td><td><code>docker info</code>（若连接失败说明引擎未启动）</td></tr><tr><td><code>docker ps</code></td><td>列出正在运行的容器</td><td><code>docker ps</code>（加 <code>-a</code> 列出包括已停止的）</td></tr><tr><td><code>docker images</code></td><td>列出本地已有的镜像</td><td><code>docker images</code></td></tr><tr><td><code>docker pull 镜像名</code></td><td>拉取镜像到本地</td><td><code>docker pull nginx:latest</code></td></tr><tr><td><code>docker run -d -p 端口:端口 镜像</code></td><td>运行容器并映射端口</td><td><code>docker run -d -p 8080:80 nginx</code></td></tr><tr><td><code>docker exec -it 容器名 bash</code></td><td>进入容器内的交互式 shell</td><td><code>docker exec -it mynginx bash</code></td></tr><tr><td><code>docker compose up -d</code></td><td>按 compose 文件启动一组容器</td><td><code>docker compose up -d</code>（在工程目录内执行）</td></tr><tr><td><code>docker logs 容器名</code></td><td>查看容器日志</td><td><code>docker logs -f mynginx</code>（<code>-f</code> 持续跟踪）</td></tr><tr><td><code>docker system prune -a</code></td><td>清理无用镜像/容器/缓存，释放磁盘</td><td><code>docker system prune -a</code>（会提示确认）</td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-启动应用并跑起第一个-nginx-容器" tabindex="-1"><a class="header-anchor" href="#示例-1-启动应用并跑起第一个-nginx-容器" aria-hidden="true">#</a> 示例 1：启动应用并跑起第一个 Nginx 容器</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 启动 Docker 桌面版，等待菜单栏的鲸鱼图标变绿（引擎就绪）</span>
<span class="token function">open</span> <span class="token parameter variable">-a</span> Docker

<span class="token comment"># 2. 确认引擎已就绪（能正常输出信息即成功）</span>
<span class="token function">docker</span> info

<span class="token comment"># 3. 拉取官方 nginx 镜像</span>
<span class="token function">docker</span> pull nginx:latest

<span class="token comment"># 4. 以后台方式运行容器，把容器 80 端口映射到本机 8080</span>
<span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">--name</span> mynginx <span class="token parameter variable">-p</span> <span class="token number">8080</span>:80 nginx

<span class="token comment"># 5. 查看运行中的容器</span>
<span class="token function">docker</span> <span class="token function">ps</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：在浏览器打开 <code>http://localhost:8080</code> 就能看到 Nginx 的默认欢迎页，<code>docker ps</code> 里能看到一个名字为 <code>mynginx</code> 的容器。</p><h3 id="示例-2-用-docker-一键启动-mysql-做本地开发" tabindex="-1"><a class="header-anchor" href="#示例-2-用-docker-一键启动-mysql-做本地开发" aria-hidden="true">#</a> 示例 2：用 Docker 一键启动 MySQL 做本地开发</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 启动 MySQL 8 容器，映射 3306 端口，设置 root 密码，并挂载数据卷便于持久化</span>
<span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">--name</span> mymysql <span class="token punctuation">\\</span>
  <span class="token parameter variable">-p</span> <span class="token number">3306</span>:3306 <span class="token punctuation">\\</span>
  <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_ROOT_PASSWORD</span><span class="token operator">=</span>devpass <span class="token punctuation">\\</span>
  <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_DATABASE</span><span class="token operator">=</span>appdb <span class="token punctuation">\\</span>
  <span class="token parameter variable">-v</span> mysql-data:/var/lib/mysql <span class="token punctuation">\\</span>
  mysql:8

<span class="token comment"># 查看是否启动成功（STATUS 应为 Up）</span>
<span class="token function">docker</span> <span class="token function">ps</span>

<span class="token comment"># 用 mysql 客户端连接验证（没有客户端可用 docker exec 进入容器）</span>
<span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> mymysql mysql <span class="token parameter variable">-uroot</span> <span class="token parameter variable">-pdevpass</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;SHOW DATABASES;&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：登录进去能看到 <code>appdb</code> 等数据库；即使删掉容器（<code>docker rm -f mymysql</code>），数据也保留在 <code>mysql-data</code> 卷里，下次重新 <code>docker run</code> 数据还在。</p><h3 id="示例-3-用-docker-compose-拉起一套-web-redis-环境" tabindex="-1"><a class="header-anchor" href="#示例-3-用-docker-compose-拉起一套-web-redis-环境" aria-hidden="true">#</a> 示例 3：用 docker compose 拉起一套 Web + Redis 环境</h3><p>先在工作目录新建 <code>docker-compose.yml</code>：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">services</span><span class="token punctuation">:</span>
  <span class="token key atrule">web</span><span class="token punctuation">:</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> nginx<span class="token punctuation">:</span>latest
    <span class="token key atrule">ports</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token string">&quot;8080:80&quot;</span>
  <span class="token key atrule">cache</span><span class="token punctuation">:</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> redis<span class="token punctuation">:</span><span class="token number">7</span>
    <span class="token key atrule">ports</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token string">&quot;6379:6379&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后在同一目录执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 按 compose 文件在后台启动全部服务</span>
<span class="token function">docker</span> compose up <span class="token parameter variable">-d</span>

<span class="token comment"># 查看服务列表与状态</span>
<span class="token function">docker</span> compose <span class="token function">ps</span>

<span class="token comment"># 跟踪 web 容器日志</span>
<span class="token function">docker</span> compose logs <span class="token parameter variable">-f</span> web

<span class="token comment"># 停止并移除这套环境</span>
<span class="token function">docker</span> compose down
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：一条命令同时起好 Nginx 和 Redis 两个容器，且能用 <code>docker compose ps</code> 统一查看状态，适合本地搭多服务开发环境。</p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><ol><li><p><strong>资源限制</strong>：打开 Docker.app → 顶部菜单栏鲸鱼图标 → Settings → Resources，可调整 <strong>CPUs</strong>（CPU 核数）、<strong>Memory</strong>（内存，默认约 2GB）、<strong>Disk image size</strong>（虚拟磁盘大小，默认约 64GB）。做重活（跑大镜像、多容器）时把内存调到 4GB 以上能显著提速；磁盘空间紧张时可在此调大上限。</p></li><li><p><strong>镜像加速（国内拉取提速）</strong>：在 Settings → Docker Engine 的 JSON 配置里加入 <code>&quot;registry-mirrors&quot;</code> 字段，填入可用的镜像加速地址（如 DaoCloud、中科大等镜像站），保存并重启 Docker。这会大幅加快 <code>docker pull</code> 的速度：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;registry-mirrors&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;https://docker.m.daocloud.io&quot;</span><span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>配置与数据位置</strong>：docker-desktop 的引擎数据、镜像、卷都存放在其内置虚拟磁盘（<code>~/Library/Containers/com.docker.docker</code> 下）中，而非系统根目录，卸载应用或清理时不需担心污染磁盘根分区。日常的 <code>docker</code> 配置（daemon.json、注册表登录态）也由应用统一管理，命令行里改完需在应用里重启引擎生效。</p></li><li><p><strong>与其它工具搭配</strong>：</p><ul><li>与 <code>docker compose</code>（v2 已内置）搭配编排多容器工程，是开发环境标配；</li><li>与 <code>docker-compose</code> 的旧版脚本配合：旧工程可 <code>brew install docker-compose</code>，新工程优先用内置的 <code>docker compose</code> 子命令；</li><li>配合 VS Code 的 Docker 插件，可在编辑器里可视化浏览镜像、容器并右键启停，图形界面与命令行互补；</li><li>与 <code>lsof</code>/<code>nc</code> 排查端口冲突：先 <code>lsof -nP -iTCP:8080 -sTCP:LISTEN</code> 看端口被谁占用，再决定是否调整 <code>-p</code> 映射。</li></ul></li></ol><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><ol><li><p><strong>必须启动 Docker.app 后引擎才可用</strong>：<code>docker</code> 命令单独安装/升级 cask 不会自动拉起守护进程。出现 <code>Cannot connect to the Docker daemon</code> 或 <code>connection refused</code> 时，先打开 Docker.app 等菜单栏图标变绿再重试。</p></li><li><p><strong>首次启动需要授权与许可</strong>：第一次打开 Docker.app 会弹「Accept terms」（接受许可）、询问是否安装内核扩展/使用虚拟化，需要输入 macOS 管理员密码并允许。若被系统拒绝或安装失败，通常在系统设置 → 隐私与安全里允许对应扩展后重启应用即可。</p></li><li><p><strong>Windows 老镜像或架构不匹配</strong>：macOS（Apple Silicon 或 Intel）默认按本机架构拉镜像。碰到提示 <code>no matching manifest for linux/amd64</code> 或无法运行 x86 镜像时，可在 Docker Desktop Settings → Docker Engine 的 JSON 里加上 <code>&quot;platform&quot;: &quot;linux/amd64&quot;</code> 或改用 <code>docker run --platform linux/amd64</code> 显式指定架构。</p></li><li><p><strong>磁盘占用增长很快</strong>：镜像、卷、日志累积会让内置虚拟磁盘膨胀，导致 macOS 磁盘空间报警。定期用 <code>docker system prune -a</code>（慎用 <code>-a</code>，会删所有未使用的镜像）清理，或在 Settings → Resources 查看并调整 Disk image size。</p></li><li><p><strong>端口映射冲突</strong>：<code>docker run -p 8080:80</code> 如果 8080 已被本机其它程序占用，会报 <code>port is already allocated</code>。先用 <code>lsof -nP -iTCP:8080 -sTCP:LISTEN</code> 查占用，换一个端口或停掉占用程序再重试。</p></li><li><p><strong>数据要挂卷持久化</strong>：容器一旦删除，未挂卷的数据会随之丢失。重要数据（数据库、上传文件）务必用 <code>-v 卷名:容器路径</code> 挂卷，避免 <code>docker rm</code> 后数据消失。</p></li><li><p><strong>引擎重启后资源设置生效</strong>：在 Settings 里改 CPU/内存/磁盘后需要点「Apply &amp; Restart」重启引擎才生效；重启期间所有容器会中断，请避免在生产式任务中直接重启。</p></li></ol>`,29),d=[c];function t(r,i){return n(),s("div",null,d)}const k=e(o,[["render",t],["__file","docker-desktop.html.vue"]]);export{k as default};
